names=[]
for m in re.finditer(rb"\x4e\x75", code):
    i=m.end()
    if i<len(code):
        b=code[i]
        if 0x80<=b<=0x9f:
            n=b&0x7f; s=code[i+1:i+1+n]
            if all(32<c<127 for c in s): names.append((m.start(), s.decode()))
        elif 0x20 < b < 0x7f:  # fixed-length 8-char form
            s=code[i:i+8]
            if all(32<=(c&0x7f)<127 for c in s): names.append((m.start(), "fixed:"+bytes(c&0x7f for c in s).decode()))
# map to function start = preceding link
asm=open(p+"ft.asm").read().splitlines()
links=[int(l.split(":")[0],16) for l in asm if " link.w " in l]
for off,n in names:
    start=max([l for l in links if l<off], default=None)
    print(f"func@{start if start is None else hex(start)} rts@{off:05x} {n}")
print(len(names))
# also printable strings
for m in re.finditer(rb"[\x20-\x7e]{6,}", code): print(hex(m.start()), m.group())

